import logging
import os
import subprocess
from ta_ue_plugin_android.uepc.ue_manager_exceptions import QcatExeNotFoundError
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra


class QmdlDecoder(object):
    """Class with utils to decode qmdl files"""

    def __init__(self, qmdl_file_path, qcat_exe_path, qcat_analyzer=None, rrc_filter_file_path=None):
        """

        :param qmdl_file_path:
        :param qcat_exe_path:
        """
        self.qmdl_file_path = qmdl_file_path
        self.qcat_exe_path = qcat_exe_path
        self.qcat_analyzer = qcat_analyzer
        self.rrc_filter_part_of_qcat_cmd = self._get_rrc_filter_cmd(rrc_filter_file_path)
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'RRC_MSGS'})
        self.logger.debug("TAUE-1275\nqmdl_file_path={}\nqcat_exe_path={}\nqcat_analyzer={}".format(qmdl_file_path,
                                                                                                    qcat_exe_path,
                                                                                                    qcat_analyzer))

    def _get_rrc_filter_cmd(self, rrc_filter_file_path):
        if rrc_filter_file_path is None:
            return None
        return '-filter="{}"'.format(rrc_filter_file_path)

    def _get_qcat_cmd(self):
        if os.path.isfile(self.qcat_exe_path):
            cmd_qcat = '"{qcat_exe_path}" -txt "{qmdl_file_path}"'.format(qcat_exe_path=self.qcat_exe_path, qmdl_file_path=self.qmdl_file_path)
            if self.rrc_filter_part_of_qcat_cmd:
                cmd_qcat = '{} {}'.format(cmd_qcat, self.rrc_filter_part_of_qcat_cmd)
            self.logger.debug('QCAT cmd to run: {}'.format(cmd_qcat))
            return cmd_qcat
        raise QcatExeNotFoundError('QCAT exe file {} not found on UE PC!'.format(self.qcat_exe_path))

    def _get_qcat_cmd_with_analyzer(self, output_dir):
        if os.path.isfile(self.qcat_exe_path):
            cmd_qcat = '"{}" -export -outputdir="{}" -analyzer="{}" "{}"'.format(self.qcat_exe_path,
                                                                                 output_dir,
                                                                                 self.qcat_analyzer,
                                                                                 self.qmdl_file_path)
            self.logger.debug('QCAT cmd to run: {}'.format(cmd_qcat))
            return cmd_qcat
        raise QcatExeNotFoundError('QCAT exe file {} not found on UE PC!'.format(self.qcat_exe_path))

    def decode_qmdl_file(self):
        """Method converting qmdl file to .txt"""
        cmd_qcat = self._get_qcat_cmd()
        out = subprocess.Popen(cmd_qcat).communicate()
        self.logger.debug('Result of running qcat: {}'.format(out))

    def analyze_qmdl_file(self, analyzer_output_path):
        """Method analyzing qmdl file and saving result to .txt in output dir"""
        self.logger.debug("Analyzing qmdl file...")
        try:
            os.mkdir(analyzer_output_path)
        except Exception as e:
            self.logger.error('Tried to create {} directory, but failed due to exception: {}'.format(
                analyzer_output_path, e))
        cmd_qcat = self._get_qcat_cmd_with_analyzer(analyzer_output_path)
        out = subprocess.Popen(cmd_qcat).communicate()
        self.logger.debug('Result of running analyze_qmdl_file qcat: {}'.format(out))


if __name__ == "__main__":
    qmdl_decoder = QmdlDecoder('C:\\diag_log_20150606_074912.qmdl',
                               'C:/Program Files (x86)/Qualcomm/QCAT 6.x/Bin/qcat.exe')
    qmdl_decoder.decode_qmdl_file()
